import{_ as e,c as i,o as t,a2 as l}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"安裝說明","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/installation.md","filePath":"zh-TW/guide/installation.md","lastUpdated":1793163976000}'),s={name:"zh-TW/guide/installation.md"};function o(r,a,n,p,h,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="安裝說明" tabindex="-1">安裝說明 <a class="header-anchor" href="#安裝說明" aria-label="Permalink to &quot;安裝說明&quot;">​</a></h1><p>NueZip 可透過 Mac App Store 在 macOS 上取得。</p><h2 id="下載選項" tabindex="-1">下載選項 <a class="header-anchor" href="#下載選項" aria-label="Permalink to &quot;下載選項&quot;">​</a></h2><h3 id="mac-app-store-推薦" tabindex="-1">Mac App Store（推薦） <a class="header-anchor" href="#mac-app-store-推薦" aria-label="Permalink to &quot;Mac App Store（推薦）&quot;">​</a></h3><ul><li><strong>下載</strong>：<a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">Mac App Store 上的 NueZip</a></li></ul><p>Mac App Store 版本提供自動更新，並與 macOS 無縫整合。</p><h3 id="github-releases-替代方案" tabindex="-1">GitHub Releases（替代方案） <a class="header-anchor" href="#github-releases-替代方案" aria-label="Permalink to &quot;GitHub Releases（替代方案）&quot;">​</a></h3><p>如果您偏好直接下載，可以從 <a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 取得 App。請注意，此版本不會收到自動更新。</p><h2 id="安裝步驟" tabindex="-1">安裝步驟 <a class="header-anchor" href="#安裝步驟" aria-label="Permalink to &quot;安裝步驟&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>點擊上方的下載連結，或在 Mac App Store 中搜尋「NueZip」</li><li>點擊「取得」以下載 App</li><li>App 會自動下載並安裝</li><li>從「應用程式」資料夾或 Launchpad 啟動 NueZip</li></ol><h3 id="github-releases" tabindex="-1">GitHub Releases <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;GitHub Releases&quot;">​</a></h3><ol><li>從 Releases 頁面下載最新的 <code>.dmg</code></li><li>雙擊下載的 <code>.dmg</code> 以開啟它</li><li>將 <code>NueZip.app</code> 圖示拖曳到您的 <code>Applications</code> 資料夾</li><li>退出已掛載的映像檔，並從 <code>Applications</code> 開啟 <code>NueZip</code></li></ol><p>若 macOS 阻止開啟 App（Gatekeeper），請開啟 <strong>系統設定 → 隱私權與安全性</strong>，針對 NueZip 點擊 <strong>仍要開啟</strong>，或右鍵點擊 App 並選擇 <strong>開啟</strong>。</p><h2 id="首次啟動" tabindex="-1">首次啟動 <a class="header-anchor" href="#首次啟動" aria-label="Permalink to &quot;首次啟動&quot;">​</a></h2><p>當您首次啟動 NueZip 時，會引導您完成一個新手設定流程：</p><ul><li><strong>授予資料夾存取權</strong>：允許 NueZip 存取常見的目錄（下載、文件、桌面）</li><li><strong>啟用 Finder 擴充功能</strong>：啟用右鍵選單，以便快速進行壓縮檔操作</li></ul><p>請在彈出提示時授予權限。您可以隨時在 <strong>系統設定 → 隱私權與安全性</strong> 中修改這些設定。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><ul><li><strong>Mac App Store 版本</strong>：更新由 App Store 自動處理</li><li><strong>GitHub Releases 版本</strong>：下載較新的版本，並替換 <code>Applications</code> 中的 App</li></ul><h2 id="解除安裝" tabindex="-1">解除安裝 <a class="header-anchor" href="#解除安裝" aria-label="Permalink to &quot;解除安裝&quot;">​</a></h2><p>若要解除安裝 NueZip：</p><ol><li>退出 NueZip</li><li>將 <code>NueZip.app</code> 從 <code>Applications</code> 拖曳到垃圾桶</li><li>（選用）移除 App 資料與日誌：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Logs/nuezip</span></span></code></pre></div><h2 id="系統需求" tabindex="-1">系統需求 <a class="header-anchor" href="#系統需求" aria-label="Permalink to &quot;系統需求&quot;">​</a></h2><ul><li><strong>macOS</strong>：建議 Sonoma（14）或更新版本</li><li><strong>CPU</strong>：Apple Silicon（M 系列）或 Intel（64 位元）</li><li><strong>記憶體</strong>：最低 4GB，建議 8GB</li><li><strong>儲存空間</strong>：約 50 MB</li></ul><h2 id="疑難排解" tabindex="-1">疑難排解 <a class="header-anchor" href="#疑難排解" aria-label="Permalink to &quot;疑難排解&quot;">​</a></h2><p>如果您在安裝過程中遇到問題：</p><ul><li><strong>macOS 阻擋 App</strong>：開啟 <strong>系統設定 → 隱私權與安全性</strong>，針對 NueZip 點擊 <strong>仍要開啟</strong></li><li><strong>公證（notarization）警告</strong>：從 Mac App Store 下載已簽署/已公證的版本</li></ul><p>如需更多協助，請參閱<a href="./troubleshooting.html">疑難排解指南</a>。</p>`,30)])])}const g=e(s,[["render",o]]);export{u as __pageData,g as default};
